// Mock JSON-RPC endpoint for testing workers/collect.reserves.js
// - eth_blockNumber -> fixed head
// - eth_call: allPairsLength / allPairs(i) / getReserves
// - simulates a 429 storm on the first N getReserves calls
// - one "bad pair" always fails with -32005
// - logs arrival timestamps of calls to check QPS
const http = require('http');
const fs = require('fs');

const PORT = Number(process.env.MOCK_PORT || 8545);
const HEAD = Number(process.env.MOCK_HEAD || 2000);
const PAIR_COUNT = Number(process.env.MOCK_PAIRS || 6);
const STORM_CALLS = Number(process.env.MOCK_STORM || 8); // first N getReserves calls -> 429
const BAD_PAIR_INDEX = Number(process.env.MOCK_BAD_PAIR || 2); // always -32005
const TIMING_LOG = process.env.MOCK_TIMING_LOG || '';

const FACTORY = '0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f'.toLowerCase();
const SEL = {
    allPairsLength: '0x574f2ba3',
    allPairs: '0x1e3dd18b',
    getReserves: '0x0902f1ac',
};
const pairs = [];
for (let i = 0; i < PAIR_COUNT; i++) {
    pairs.push('0x' + String(i + 1).padStart(40, '0'));
}
const BAD_PAIR = pairs[BAD_PAIR_INDEX];

let reservesCalls = 0;
const timings = [];

function enc32(hex) { return hex.padStart(64, '0'); }
function encNum(n) { return enc32(BigInt(n).toString(16)); }
function encAddr(a) { return enc32(a.replace('0x', '').toLowerCase()); }

function handleCall(to, data) {
    to = (to || '').toLowerCase();
    const sel = (data || '').slice(0, 10);
    if (to === FACTORY && sel === SEL.allPairsLength) {
        return { result: '0x' + encNum(PAIR_COUNT) };
    }
    if (to === FACTORY && sel === SEL.allPairs) {
        const idx = Number(BigInt('0x' + data.slice(10)));
        return { result: '0x' + encAddr(pairs[idx]) };
    }
    if (pairs.includes(to) && sel === SEL.getReserves) {
        reservesCalls++;
        timings.push(Date.now());
        if (reservesCalls <= STORM_CALLS) {
            return { httpStatus: 429, body: '429 Too Many Requests: rate limit exceeded' };
        }
        if (to === BAD_PAIR) {
            return { error: { code: -32005, message: 'limit exceeded -32005' } };
        }
        const r0 = 1000000n + BigInt(reservesCalls);
        const r1 = 2000000n + BigInt(reservesCalls);
        return { result: '0x' + encNum(r0) + encNum(r1) + encNum(1700000000) };
    }
    return { error: { code: -32601, message: 'method not found (mock)' } };
}

const server = http.createServer((req, res) => {
    let body = '';
    req.on('data', c => body += c);
    req.on('end', () => {
        let out;
        try {
            const reqJson = JSON.parse(body);
            if (reqJson.method === 'eth_blockNumber') {
                out = { jsonrpc: '2.0', id: reqJson.id, result: '0x' + HEAD.toString(16) };
            } else if (reqJson.method === 'eth_call') {
                const [call] = reqJson.params;
                const r = handleCall(call.to, call.data);
                if (r.httpStatus) {
                    res.writeHead(r.httpStatus, { 'Content-Type': 'text/plain' });
                    res.end(r.body);
                    return;
                }
                out = { jsonrpc: '2.0', id: reqJson.id };
                if (r.error) out.error = r.error; else out.result = r.result;
            } else if (reqJson.method === 'eth_chainId' || reqJson.method === 'net_version') {
                out = { jsonrpc: '2.0', id: reqJson.id, result: reqJson.method === 'net_version' ? '80002' : '0x13882' };
            } else {
                out = { jsonrpc: '2.0', id: reqJson.id, error: { code: -32601, message: 'not supported: ' + reqJson.method } };
            }
        } catch (e) {
            res.writeHead(500); res.end(String(e)); return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(out));
    });
});

server.listen(PORT, () => console.log(`mock rpc on :${PORT} head=${HEAD} pairs=${PAIR_COUNT} storm=${STORM_CALLS} badPair=${BAD_PAIR}`));

process.on('SIGTERM', dump);
process.on('SIGINT', dump);
function dump() {
    if (TIMING_LOG) fs.writeFileSync(TIMING_LOG, JSON.stringify({ timings, reservesCalls }, null, 2));
    console.log(`getReserves calls seen: ${reservesCalls}`);
    process.exit(0);
}

